mapper.select:
SELECT A.ACCOUNT_ID, U.USER_NO, U.USER_NAME, A.INST_ID, A.DEPT_ID, D.DEPT_NAME, A.LOGIN_ID, A.PASSWORD, A.CREATE_DT, A.UPDATE_DT, A.DEL_YN, A.CREATE_ID, A.UPDATE_ID, A.ACCOUNT_STATUS_CD, CC.CODE_NAME AS ACCOUNT_STATUS_NAME, A.PWD_FAIL_CNT, A.PWD_CHANGE_DT FROM t1000_account A JOIN t1000_user U ON A.USER_NO = U.USER_NO LEFT JOIN t1000_department D ON A.DEPT_ID = D.DEPT_ID LEFT JOIN total_code CC ON A.ACCOUNT_STATUS_CD = CC.CODE_ID AND CC.GROUP_ID = 'B0' WHERE A.IS_SYSTEM = 'N' AND A.INST_ID = #{instId} AND A.DEL_YN = 'N'
AND A.LOGIN_ID LIKE '%' || #{loginId} || '%'
AND U.USER_NAME LIKE '%' || #{userName} || '%'
AND A.DEPT_ID = #{deptId}
AND A.ACCOUNT_STATUS_CD = #{accountStatus}
AND A.CREATE_DT >= #{startDate}
AND A.CREATE_DT <= #{endDate}
ORDER BY A.CREATE_DT DESC
